Determine if these two pointers MUST alias (always point to the same location), MAY alias (might point to the same location), or MUST-NOT alias (never point to the same location) after the execution of the function.

Program to analyze:
control_check_subs_pane(struct client *c, struct control_sub *csub)
{
	struct session		*s = c->session;
	struct window_pane	*wp;
	struct window		*w;
	struct winlink		*wl;
	struct format_tree	*ft;
	char			*value;
	struct control_sub_pane	*csp, find;

	wp = window_pane_find_by_id(csub->id);
	if (wp == NULL || wp->fd == -1)
		return;
	w = wp->window;

	TAILQ_FOREACH(wl, &w->winlinks, wentry) {
		if (wl->session != s)
			continue;

		ft = format_create_defaults(NULL, c, s, wl, wp);
		value = format_expand(ft, csub->format);
		format_free(ft);

		find.pane = wp->id;
		find.idx = wl->idx;

		csp = RB_FIND(control_sub_panes, &csub->panes, &find);
		if (csp == NULL) {
			csp = xcalloc(1, sizeof *csp);
			csp->pane = wp->id;
			csp->idx = wl->idx;
			RB_INSERT(control_sub_panes, &csub->panes, csp);
		}

		if (csp->last != NULL && strcmp(value, csp->last) == 0) {
			free(value);
			continue;
		}
		control_write(c,
		    "%%subscription-changed %s $%u @%u %u %%%u : %s",
		    csub->name, s->id, w->id, wl->idx, wp->id, value);
		free(csp->last);
		csp->last = value;
	}
}


